// Store methods
Object.defineProperty(store, 'isAuthenticated', {get(){return !!this.user&&!!this.token}});
Object.defineProperty(store, 'unreadCount', {get(){return this.notifications.filter(n=>!n.read).length}});
store.empById = function(id){return this.employees.find(e=>e.id===id);};
store.login = function(email,password){
  const users=[
    {email:'manager@shaffoftir.uz',password:'manager123',name:'Teshaboyev Jasur',role:'MANAGER',rank:'Polkovnik'},
    {email:'instructor@shaffoftir.uz',password:'inst123',name:'Karimov Baxtiyor',role:'INSTRUCTOR',rank:'Mayor'},
    {email:'employee@shaffoftir.uz',password:'emp123',name:'Ergashev Sherzod',role:'EMPLOYEE',rank:'Serjant'},
  ];
  const u=users.find(x=>x.email===email&&x.password===password);
  if(!u) return false;
  this.user={email:u.email,name:u.name,role:u.role,rank:u.rank};
  this.token='tok_'+Date.now();
  try{localStorage.setItem('stir_auth',JSON.stringify({user:this.user,token:this.token}));}catch(e){}
  return true;
};
store.logout = function(){this.user=null;this.token=null;try{localStorage.removeItem('stir_auth');}catch(e){}};
store.canAccess = function(page){
  if(!this.user) return false;
  const map={MANAGER:['dashboard','sessions','employees','training','cameras','reports','settings','profile'],INSTRUCTOR:['dashboard','sessions','employees','training','cameras','reports','settings','profile'],EMPLOYEE:['sessions','training','profile']};
  return (map[this.user.role]||[]).includes(page);
};
store.approveBooking=function(id){const b=this.bookings.find(x=>x.id===id);if(b)b.status='approved';};
store.rejectBooking=function(id){const b=this.bookings.find(x=>x.id===id);if(b)b.status='rejected';};
store.markAllRead=function(){this.notifications.forEach(n=>n.read=true);};
store.addBooking=function(data){
  const c=this.bookings.find(b=>b.date===data.date&&b.lane===data.lane&&b.time===data.time&&b.status!=='rejected');
  if(c) return {error:data.lane+' '+data.time+' band qilingan'};
  this.bookings.push({id:'b'+Date.now(),...data,status:'pending'});
  return {success:true};
};

try{const s=localStorage.getItem('stir_auth');if(s){const d=JSON.parse(s);store.user=d.user;store.token=d.token;}}catch(e){}

