const TrainingPage = {
  setup(){const s=inject(STORE_KEY);const tab=ref('plans');const selPlan=ref(null);const selAssign=ref(null);return{s,tab,selPlan,selAssign,ICONS};},
  template:`<div><div class="tab-bar"><div class="tab" :class="{active:tab==='plans'}" @click="tab='plans'">O'quv-rejalar</div><div class="tab" :class="{active:tab==='active'}" @click="tab='active'">Davom etayotgan ({{s.trainAssigns.filter(a=>a.status==='in-progress').length}})</div><div class="tab" :class="{active:tab==='done'}" @click="tab='done'">Yakunlangan</div></div><div v-if="tab==='plans'" class="grid" style="grid-template-columns:repeat(auto-fill,minmax(300px,1fr))"><div v-for="p in s.trainPlans" :key="p.id" class="training-card" @click="selPlan=p"><div style="aspect-ratio:16/9;background:var(--surface2);border-radius:8px;margin-bottom:12px;display:flex;align-items:center;justify-content:center;position:relative"><span style="font-size:48px">{{p.icon}}</span><div v-if="p.video" style="position:absolute;top:8px;right:8px;background:rgba(0,0,0,.6);border-radius:4px;padding:2px 6px;font-size:10px;color:#fff;display:flex;align-items:center;gap:3px"><span v-html="ICONS.video" style="width:12px"></span>VIDEO</div></div><div style="font-size:14px;font-weight:600;margin-bottom:4px">{{p.title}}</div><div style="font-size:12px;color:var(--text3);margin-bottom:10px">{{p.desc}}</div><div style="display:flex;gap:6px"><span :class="'badge '+(p.level==='BEGINNER'?'badge-gray':p.level==='INTERMEDIATE'?'badge-blue':p.level==='ADVANCED'?'badge-amber':'badge-green')">{{p.level}}</span><span class="tag">{{p.lessons}} dars</span><span class="tag">{{p.duration}}</span></div></div></div><div v-if="tab==='active'"><div v-for="a in s.trainAssigns.filter(x=>x.status==='in-progress')" :key="a.id" class="card" style="margin-bottom:12px"><div style="display:flex;align-items:center;gap:12px;margin-bottom:12px"><div class="avatar">{{(s.empById(a.employeeId)||{name:'?'}).name[0]}}</div><div style="flex:1"><div style="font-size:14px;font-weight:500">{{(s.empById(a.employeeId)||{name:'Xodim'}).name}}</div><div style="font-size:12px;color:var(--text3)">{{a.planTitle}}</div></div><span class="badge badge-amber"><span class="live-dot" style="margin-right:4px"></span>Davom etmoqda</span><button class="btn btn-primary btn-sm" @click="selAssign=a">Ko'rish</button></div><div class="progress"><div class="progress-bar" :style="{width:a.progress+'%',background:'var(--brand)'}"></div></div><div style="display:flex;justify-content:space-between;font-size:11px;color:var(--text3);margin-top:4px"><span>{{a.progress}}%</span><span v-if="a.lane">{{a.lane}}</span></div></div></div><div v-if="tab==='done'" class="card" style="padding:0;overflow:hidden"><table><thead><tr><th>Xodim</th><th>Reja</th><th>Progress</th><th>Holat</th></tr></thead><tbody><tr v-for="a in s.trainAssigns.filter(x=>x.status==='completed')" :key="a.id"><td>{{(s.empById(a.employeeId)||{name:'?'}).name}}</td><td>{{a.planTitle}}</td><td><span class="badge badge-green">{{a.progress}}%</span></td><td><span class="badge badge-green">Yakunlandi</span></td></tr></tbody></table></div><div v-if="selPlan" class="modal-overlay" @click.self="selPlan=null"><div class="modal" style="max-width:660px"><div class="modal-header"><span style="font-size:14px;font-weight:600">{{selPlan.title}}</span><button class="btn btn-ghost btn-sm" @click="selPlan=null" v-html="ICONS.x"></button></div><div class="modal-body"><div style="aspect-ratio:16/9;background:var(--surface2);border-radius:8px;margin-bottom:16px;display:flex;align-items:center;justify-content:center;position:relative"><span style="font-size:64px">{{selPlan.icon}}</span><button v-if="selPlan.video" class="btn btn-primary" style="position:absolute"><span v-html="ICONS.play" style="width:14px"></span> Videoni ko'rish</button></div><div style="font-size:13px;color:var(--text2);margin-bottom:16px">{{selPlan.desc}}</div><div class="card-title">Darslar ({{selPlan.lessons}})</div><div v-for="i in selPlan.lessons" :key="i" style="padding:10px 0;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:10px"><div style="width:26px;height:26px;border-radius:50%;background:var(--surface2);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:600">{{i}}</div><div style="flex:1"><div style="font-size:13px;font-weight:500">Dars {{i}}: Amaliy mashq</div><div style="font-size:11px;color:var(--text3)">20 daqiqa</div></div><span v-html="ICONS.play" style="width:16px;color:var(--brand);cursor:pointer"></span></div></div></div></div><div v-if="selAssign" class="modal-overlay" @click.self="selAssign=null"><div class="modal" style="max-width:820px"><div class="modal-header"><span style="font-size:14px;font-weight:600">{{(s.empById(selAssign.employeeId)||{name:'Xodim'}).name}} — Jonli kuzatuv</span><button class="btn btn-ghost btn-sm" @click="selAssign=null" v-html="ICONS.x"></button></div><div class="modal-body"><div class="grid" style="grid-template-columns:1fr 1fr;gap:16px"><div><div style="font-size:12px;font-weight:600;color:var(--text2);margin-bottom:8px;display:flex;align-items:center;gap:6px"><span class="live-dot"></span> Kamera ({{selAssign.lane}})</div><div style="aspect-ratio:4/3;background:#000;border-radius:8px;position:relative;display:flex;align-items:center;justify-content:center"><div style="position:absolute;inset:0;background:linear-gradient(135deg,#0d0d1a,#1a1a2e)"></div><span v-html="ICONS.camera" style="position:relative;width:40px;color:var(--text3)"></span><div style="position:absolute;top:8px;left:8px;font-size:10px;color:var(--red);font-weight:700;display:flex;align-items:center;gap:4px"><span class="live-dot"></span>LIVE</div></div></div><div><div style="font-size:12px;font-weight:600;color:var(--text2);margin-bottom:8px">3D Nishon (Real-time)</div><div style="aspect-ratio:4/3;background:var(--surface2);border-radius:8px;display:flex;align-items:center;justify-content:center"><svg viewBox="0 0 200 200" style="width:80%;height:80%"><circle cx="100" cy="100" r="90" fill="none" stroke="#27272a" stroke-width="2"/><circle cx="100" cy="100" r="70" fill="none" stroke="#27272a" stroke-width="2"/><circle cx="100" cy="100" r="50" fill="none" stroke="#27272a" stroke-width="2"/><circle cx="100" cy="100" r="30" fill="none" stroke="#27272a" stroke-width="2"/><circle cx="100" cy="100" r="15" fill="none" stroke="#ef4444" stroke-width="2"/><circle cx="100" cy="100" r="5" fill="#ef4444"/><circle cx="85" cy="95" r="5" fill="#22c55e"><animate attributeName="opacity" values="0.4;1;0.4" dur="2s" repeatCount="indefinite"/></circle><circle cx="115" cy="105" r="5" fill="#22c55e"><animate attributeName="opacity" values="0.4;1;0.4" dur="2s" repeatCount="indefinite"/></circle><circle cx="95" cy="112" r="5" fill="#f59e0b"><animate attributeName="opacity" values="0.4;1;0.4" dur="2.5s" repeatCount="indefinite"/></circle><circle cx="108" cy="88" r="5" fill="#22c55e"><animate attributeName="opacity" values="0.4;1;0.4" dur="1.8s" repeatCount="indefinite"/></circle></svg></div></div></div><div style="display:flex;justify-content:space-around;margin-top:16px;padding-top:16px;border-top:1px solid var(--border)"><div style="text-align:center"><div style="font-size:24px;font-weight:700;color:var(--green)">4</div><div style="font-size:11px;color:var(--text3)">Aniq tegsa</div></div><div style="text-align:center"><div style="font-size:24px;font-weight:700;color:var(--red)">1</div><div style="font-size:11px;color:var(--text3)">Tegmagan</div></div><div style="text-align:center"><div style="font-size:24px;font-weight:700;color:var(--brand)">{{selAssign.progress}}%</div><div style="font-size:11px;color:var(--text3)">Progress</div></div></div></div></div></div></div>`
};

// ─── CAMERAS ───────────────────────────────────────────────
const CamerasPage = {
  setup(){const s=inject(STORE_KEY);const locations=computed(()=>[...new Set(s.cameras.map(c=>c.location))]);return{s,locations,ICONS};},
  template:`<div><div class="grid" style="grid-template-columns:repeat(4,1fr);margin-bottom:16px"><div class="stat-card"><div class="stat-label">Jami</div><div class="stat-value">{{s.cameras.length}}</div></div><div class="stat-card"><div class="stat-label">Online</div><div class="stat-value" style="color:var(--green)">{{s.cameras.filter(c=>c.status==='online').length}}</div></div><div class="stat-card"><div class="stat-label">Offline</div><div class="stat-value" style="color:var(--red)">{{s.cameras.filter(c=>c.status==='offline').length}}</div></div><div class="stat-card"><div class="stat-label">Joylar</div><div class="stat-value">{{locations.length}}</div></div></div><div v-for="loc in locations" :key="loc" style="margin-bottom:20px"><div style="font-size:14px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:6px"><span v-html="ICONS.map" style="width:16px;color:var(--brand)"></span>{{loc}}</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px"><div v-for="c in s.cameras.filter(x=>x.location===loc)" :key="c.id" class="cam-card"><div class="cam-feed"><div v-if="c.status==='online'" style="position:absolute;inset:0;background:linear-gradient(135deg,#0d0d1a,#1a1a2e);display:flex;align-items:center;justify-content:center"><span v-html="ICONS.camera" style="width:28px;color:var(--text3)"></span></div><div v-else style="position:absolute;inset:0;background:#0a0a0b;display:flex;align-items:center;justify-content:center"><span v-html="ICONS.alert" style="width:28px;color:var(--red)"></span></div><div style="position:absolute;bottom:6px;left:8px;right:8px;display:flex;justify-content:space-between;font-size:10px;color:#fff"><span style="display:flex;align-items:center;gap:3px"><span v-if="c.status==='online'" class="live-dot" style="width:6px;height:6px"></span>{{c.status==='online'?'LIVE':'OFFLINE'}}</span><span>{{c.resolution}}</span></div></div><div style="padding:10px 12px"><div style="font-size:13px;font-weight:500;margin-bottom:4px">{{c.name}}</div><div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:11px;color:var(--text3)">{{c.ip}}</span><span :class="'badge '+(c.status==='online'?'badge-green':'badge-red')">{{c.status}}</span></div></div></div></div></div></div>`
};

// ─── REPORTS ──────────────────────────────────────────────
const ReportsPage = {
  setup(){const s=inject(STORE_KEY);const tab=ref('summary');const search=ref('');const filtered=computed(()=>s.protocols.filter(p=>{if(!search.value)return true;const e=s.empById(p.employeeId);return e&&e.name.toLowerCase().includes(search.value.toLowerCase());}));const stats=computed(()=>({total:s.protocols.length,signed:s.protocols.filter(p=>p.signed).length,unsigned:s.protocols.filter(p=>!p.signed).length,avg:s.protocols.length?Math.round(s.protocols.reduce((a,p)=>a+p.score,0)/s.protocols.length):0}));return{s,tab,search,filtered,stats,ICONS};},
  template:`<div><div class="tab-bar"><div class="tab" :class="{active:tab==='summary'}" @click="tab='summary'">Umumiy hisobot</div><div class="tab" :class="{active:tab==='protocols'}" @click="tab='protocols'">Protokollar ({{s.protocols.length}})</div><div class="tab" :class="{active:tab==='analytics'}" @click="tab='analytics'">Tahlil</div></div><div v-if="tab==='summary'"><div class="grid" style="grid-template-columns:repeat(4,1fr);margin-bottom:16px"><div class="stat-card"><div class="stat-label">Jami protokollar</div><div class="stat-value">{{stats.total}}</div></div><div class="stat-card"><div class="stat-label">Imzolangan</div><div class="stat-value" style="color:var(--green)">{{stats.signed}}</div></div><div class="stat-card"><div class="stat-label">Imzolanmagan</div><div class="stat-value" style="color:var(--amber)">{{stats.unsigned}}</div></div><div class="stat-card"><div class="stat-label">O'rt. ball</div><div class="stat-value">{{stats.avg}}</div></div></div><div class="card" style="padding:0;overflow:hidden"><table><thead><tr><th>Sana</th><th>Xodim</th><th>Qurol</th><th>O'q</th><th>Aniq</th><th>Ball</th><th>Imzo</th></tr></thead><tbody><tr v-for="p in s.protocols" :key="p.id"><td>{{p.date}}</td><td>{{(s.empById(p.employeeId)||{name:'?'}).name}}</td><td>{{p.weapon}}</td><td>{{p.shots}}</td><td>{{p.hits}}</td><td><b>{{p.score}}</b></td><td><span :class="'badge '+(p.signed?'badge-green':'badge-amber')">{{p.signed?'Imzolangan':'Kutilmoqda'}}</span></td></tr></tbody></table></div></div><div v-if="tab==='protocols'" class="card" style="padding:0;overflow:hidden"><div style="padding:12px 16px;border-bottom:1px solid var(--border);display:flex;gap:8px"><input class="input" style="max-width:260px" v-model="search" placeholder="Xodim bo'yicha qidirish..."><button class="btn btn-ghost btn-sm" style="margin-left:auto"><span v-html="ICONS.download" style="width:14px"></span> Eksport</button></div><table><thead><tr><th>Sana</th><th>Xodim</th><th>Qurol</th><th>O'q</th><th>Aniq</th><th>Ball</th><th>Imzo</th></tr></thead><tbody><tr v-for="p in filtered" :key="p.id"><td>{{p.date}}</td><td>{{(s.empById(p.employeeId)||{name:'?'}).name}}</td><td>{{p.weapon}}</td><td>{{p.shots}}</td><td>{{p.hits}}</td><td><b>{{p.score}}</b></td><td><span :class="'badge '+(p.signed?'badge-green':'badge-amber')">{{p.signed?'Imzolangan':'Kutilmoqda'}}</span></td></tr></tbody></table></div><div v-if="tab==='analytics'" class="grid" style="grid-template-columns:1fr 1fr"><div class="card"><div class="card-title">Qurol bo'yicha</div><table><thead><tr><th>Qurol</th><th>Sessiya</th><th>Ball</th></tr></thead><tbody><tr v-for="w in [...new Set(s.sessions.map(x=>x.weapon))]" :key="w"><td>{{w}}</td><td>{{s.sessions.filter(x=>x.weapon===w).length}}</td><td><span class="badge badge-blue">{{Math.round(s.sessions.filter(x=>x.weapon===w).reduce((a,x)=>a+x.score,0)/s.sessions.filter(x=>x.weapon===w).length)}}</span></td></tr></tbody></table></div><div class="card"><div class="card-title">Top-5 o'qchilar</div><div v-for="(e,i) in [...s.employees].sort((a,b)=>b.avgScore-a.avgScore).slice(0,5)" :key="e.id" style="padding:8px 0;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:8px"><div style="width:24px;height:24px;border-radius:50%;background:var(--surface2);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:600">{{i+1}}</div><div style="flex:1"><div style="font-size:12px;font-weight:500">{{e.name}}</div><div style="font-size:11px;color:var(--text3)">{{e.battalion}}</div></div><span class="badge badge-green">{{e.avgScore}}</span></div></div></div></div>`
};

