  template:`<div style="max-width:600px"><div class="card" style="margin-bottom:16px"><div style="display:flex;align-items:center;gap:16px;margin-bottom:20px"><div class="avatar" style="width:64px;height:64px;font-size:24px">{{s.user?.name?.[0]}}</div><div><div style="font-size:18px;font-weight:700">{{s.user?.name}}</div><div style="font-size:13px;color:var(--text3)">{{s.user?.email}}</div><div style="display:flex;gap:6px;margin-top:6px"><span :class="'badge '+(s.user?.role==='MANAGER'?'badge-purple':s.user?.role==='INSTRUCTOR'?'badge-blue':'badge-green')">{{s.user?.role}}</span><span class="badge badge-gray">{{s.user?.rank}}</span></div></div></div><div class="grid" style="grid-template-columns:1fr 1fr;gap:14px"><div><div class="label">Email</div><div>{{s.user?.email}}</div></div><div><div class="label">Unvon</div><div>{{s.user?.rank}}</div></div></div></div><div class="card"><div class="card-title">Sozlamalar</div><div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid var(--border)"><div style="font-size:13px;font-weight:500">Bildirishnomalar</div><div style="width:36px;height:20px;background:var(--green);border-radius:10px;position:relative;cursor:pointer"><div style="width:16px;height:16px;background:#fff;border-radius:50%;position:absolute;top:2px;left:18px"></div></div></div><div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0"><div style="font-size:13px;font-weight:500">3D vizualizatsiya</div><div style="width:36px;height:20px;background:var(--green);border-radius:10px;position:relative;cursor:pointer"><div style="width:16px;height:16px;background:#fff;border-radius:50%;position:absolute;top:2px;left:18px"></div></div></div></div></div>`
