// ─── APP LAYOUT ────────────────────────────────────────────
const AppLayout = {
  setup(){
    const s=inject(STORE_KEY);const router=useRouter();const route=useRoute();
    const showNotif=ref(false),showProfile=ref(false);
    const menu=[
      {id:'dashboard',label:'Boshqaruv paneli',icon:'dashboard',path:'/dashboard'},
      {id:'sessions',label:'Sessiyalar',icon:'sessions',path:'/sessions'},
      {id:'employees',label:'Xodimlar',icon:'users',path:'/employees'},
      {id:'training',label:"O'quv-rejalar",icon:'book',path:'/training'},
      {id:'cameras',label:'Kameralar',icon:'camera',path:'/cameras'},
      {id:'reports',label:'Hisobotlar',icon:'report',path:'/reports'},
      {id:'settings',label:'Sozlamalar',icon:'settings',path:'/settings'},
    ].filter(m=>s.canAccess(m.id));
    const title=computed(()=>{const m=menu.find(x=>route.path.startsWith(x.path));return m?m.label:'ShaffofTIR';});
    function logout(){s.logout();router.push('/login');}
    return {s,menu,title,showNotif,showProfile,logout,route,ICONS};
  },
  template:`<div class="app-layout"><aside class="sidebar"><div class="sidebar-logo"><span v-html="ICONS.target" style="color:var(--brand);width:24px;flex-shrink:0"></span><span>ShaffofTIR</span></div><nav style="flex:1;padding:8px 0"><div v-for="m in menu" :key="m.id" class="nav-item" :class="{active:route.path.startsWith(m.path)}" @click="$router.push(m.path)"><span v-html="ICONS[m.icon]" style="width:18px;flex-shrink:0"></span><span>{{m.label}}</span></div></nav><div style="padding:10px;border-top:1px solid var(--border)"><div style="display:flex;align-items:center;gap:8px;padding:6px"><div class="avatar" style="width:30px;height:30px;font-size:11px">{{s.user?.name?.[0]}}</div><div style="min-width:0;flex:1"><div style="font-size:12px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">{{s.user?.name}}</div><div style="font-size:11px;color:var(--text3)">{{s.user?.role}}</div></div></div></div></aside><div class="main-area"><header class="topbar"><div style="font-size:15px;font-weight:600">{{title}}</div><div style="flex:1"></div><div style="position:relative"><button class="btn btn-ghost" style="padding:6px 10px;position:relative" @click="showNotif=!showNotif;showProfile=false"><span v-html="ICONS.bell" style="width:20px"></span><span v-if="s.unreadCount>0" style="position:absolute;top:2px;right:2px;width:16px;height:16px;border-radius:50%;background:var(--red);color:#fff;font-size:9px;display:flex;align-items:center;justify-content:center;font-weight:700">{{s.unreadCount}}</span></button><div v-if="showNotif" style="position:absolute;top:100%;right:0;margin-top:4px;background:var(--surface);border:1px solid var(--border);border-radius:10px;width:340px;z-index:200;box-shadow:0 8px 24px rgba(0,0,0,.4)"><div style="padding:12px 14px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center"><span style="font-size:13px;font-weight:600">Bildirishnomalar</span><button class="btn btn-ghost btn-sm" @click="s.markAllRead()">Hammasini o'qildi</button></div><div v-for="n in s.notifications" :key="n.id" style="padding:10px 14px;border-bottom:1px solid var(--border);cursor:pointer" :style="{background:n.read?'':'rgba(99,102,241,.04)'}"><div style="display:flex;gap:6px;align-items:center;margin-bottom:2px"><span :class="'badge badge-'+(n.type==='success'?'green':n.type==='error'?'red':n.type==='warning'?'amber':'blue')">{{n.type}}</span><span style="font-size:12px;font-weight:500">{{n.title}}</span></div><div style="font-size:11px;color:var(--text3)">{{n.desc}}</div><div style="font-size:10px;color:var(--text3);margin-top:2px">{{n.time}}</div></div></div></div><div style="position:relative"><button class="btn btn-ghost" style="padding:4px 8px" @click="showProfile=!showProfile;showNotif=false"><div class="avatar" style="width:28px;height:28px;font-size:11px">{{s.user?.name?.[0]}}</div></button><div v-if="showProfile" style="position:absolute;top:100%;right:0;margin-top:4px;background:var(--surface);border:1px solid var(--border);border-radius:10px;min-width:180px;z-index:200;box-shadow:0 8px 24px rgba(0,0,0,.4)"><div style="padding:10px 14px;cursor:pointer;display:flex;align-items:center;gap:8px" @click="$router.push('/profile');showProfile=false"><span v-html="ICONS.user" style="width:16px"></span>Profil</div><div style="padding:10px 14px;cursor:pointer;display:flex;align-items:center;gap:8px" @click="$router.push('/settings');showProfile=false"><span v-html="ICONS.settings" style="width:16px"></span>Sozlamalar</div><div style="padding:10px 14px;cursor:pointer;display:flex;align-items:center;gap:8px;color:var(--red)" @click="logout"><span v-html="ICONS.logout" style="width:16px"></span>Chiqish</div></div></div></header><main class="content"><router-view/></main></div></div>`
};

// ─── ROUTER ────────────────────────────────────────────────
const router = createRouter({
  history: createWebHashHistory(),
  routes: [
    {path:'/',redirect:'/dashboard'},
    {path:'/login',component:LoginPage},
    {path:'/',component:AppLayout,children:[
      {path:'dashboard',component:DashboardPage},
      {path:'sessions',component:SessionsPage},
      {path:'employees',component:EmployeesPage},
      {path:'training',component:TrainingPage},
      {path:'cameras',component:CamerasPage},
      {path:'reports',component:ReportsPage},
      {path:'settings',component:SettingsPage},
      {path:'profile',component:ProfilePage},
    ]},
    {path:'/:any(.*)*',redirect:'/dashboard'},
  ]
});

router.beforeEach((to,from,next)=>{
  if(to.path==='/login'){next();return;}
  if(!store.isAuthenticated){next('/login');return;}
  const page=to.path.split('/')[1];
  if(page&&!store.canAccess(page)){next('/dashboard');return;}
  next();
});

// ─── MOUNT ──────────────────────────────────────────────────
const app = createApp({
  setup(){provide(STORE_KEY,store);},
  template:'<router-view/>'
});
app.use(router);
app.mount('#app');
